string newPath = Tama.Args.Get(args, "newPath", "");
string refPath = Tama.Args.Get(args, "refPath", "");
long oldIdNum = Tama.Args.Get(args, "oldId", 0L);
var oldDs = doc.GetElement(new ElementId((int)oldIdNum)) as DirectShape;
if (oldDs == null) throw new Exception("Old DirectShape not found");
var catId = oldDs.Category.Id;
string appId = oldDs.ApplicationId;
bool pinned = oldDs.Pinned;

Func<string, IList<GeometryObject>> load = p => {
  var imp = new ShapeImporter(); imp.InputFormat = ShapeImporterSourceFormat.Auto; imp.SetDefaultLengthUnit(ImportUnit.Foot);
  return imp.Convert(doc, p);
};
Func<IEnumerable<GeometryObject>, double[]> minOf = gs => {
  double[] mn = {1e18,1e18,1e18};
  if (gs == null) return mn;
  foreach (var g in gs) if (g is Mesh m) foreach (var p in m.Vertices) { mn[0]=Math.Min(mn[0],p.X); mn[1]=Math.Min(mn[1],p.Y); mn[2]=Math.Min(mn[2],p.Z); }
  return mn;
};
var refMin = minOf(load(refPath));
var oldGeoElem = oldDs.get_Geometry(new Options());
if (oldGeoElem == null) throw new Exception("Old DirectShape has no geometry");
var oldMin = minOf(oldGeoElem.Cast<GeometryObject>());
var T = new XYZ(oldMin[0]-refMin[0], oldMin[1]-refMin[1], oldMin[2]-refMin[2]);

var geo = load(newPath);
if (geo == null || geo.Count == 0) throw new Exception("STL conversion returned no geometry");
var tr = Transform.CreateTranslation(T);
var shapes = new List<GeometryObject>();
foreach (var g in geo) {
  if (g is Mesh m) shapes.Add(m.get_Transformed(tr));
  else if (g is Solid s) shapes.Add(SolidUtils.CreateTransformed(s, tr));
}
var ds = DirectShape.CreateElement(doc, catId);
if (!string.IsNullOrEmpty(appId)) ds.ApplicationId = appId;
ds.ApplicationDataId = newPath;
ds.SetShape(shapes);
var oldId = oldDs.Id;
doc.Delete(oldId);
doc.Regenerate();
ds.Pinned = pinned;

double[] mn = {1e18,1e18,1e18}, mx = {-1e18,-1e18,-1e18}; int tris = 0;
var ge = ds.get_Geometry(new Options());
if (ge != null) foreach (var g in ge) if (g is Mesh m) { tris += m.NumTriangles; foreach (var p in m.Vertices) { mn[0]=Math.Min(mn[0],p.X); mn[1]=Math.Min(mn[1],p.Y); mn[2]=Math.Min(mn[2],p.Z); mx[0]=Math.Max(mx[0],p.X); mx[1]=Math.Max(mx[1],p.Y); mx[2]=Math.Max(mx[2],p.Z);} }
return new { newId = ds.Id.IntegerValue, deletedId = oldId.IntegerValue, offsetFt = new[]{T.X,T.Y,T.Z}, tris, mn, mx, pinned, shapesCount = shapes.Count };
